window.REVISION_DATA = {"grade": 9, "title": "Grade 9 Revision Lab", "tagline": "Build confidence with varied practice, clear explanations and a fresh timed challenge.", "topics": [{"id": "W1-L1", "title": "Binary and denary conversions", "summary": "Binary place values double from right to left. Add the values under 1s to obtain denary.", "tips": ["For an unsigned 8-bit number, use 128, 64, 32, 16, 8, 4, 2, 1.", "To convert denary to binary, select powers of two that add to the number.", "When eight bits are requested, keep leading zeros. They do not change the value, but they preserve the required width."]}, {"id": "W1-L2", "title": "Hexadecimal conversions", "summary": "Hexadecimal is base 16. One hexadecimal digit matches one four-bit binary group.", "tips": ["A, B, C, D, E and F stand for denary 10, 11, 12, 13, 14 and 15.", "For a two-digit hexadecimal number, multiply the left digit by 16 and add the right digit.", "Keep four-bit groups in their original left-to-right order when converting between binary and hexadecimal."]}, {"id": "W2-L1", "title": "Uses of hexadecimal", "summary": "Hexadecimal provides a shorter readable display of values such as memory addresses and diagnostic codes.", "tips": ["Explain a benefit to the person using the display: fewer digits can make long codes easier to read, compare or copy.", "Changing the displayed number system does not change the numerical value.", "Two hexadecimal digits can represent eight binary bits. Digits on a display are not the same thing as stored bits."]}, {"id": "W2-L2", "title": "Binary addition and overflow", "summary": "In binary, 1 + 1 gives 10: write 0 and carry 1. An unsigned 8-bit result must stay within 0 to 255.", "tips": ["Align the rightmost bits and add from right to left, including any carry.", "A column containing 1 + 1 + 1 gives 11: write 1 and carry 1.", "Check the complete result before discarding any leading carry. A result above 255 cannot fit in unsigned eight-bit storage."]}, {"id": "W3-L1", "title": "Logical shifts", "summary": "A logical shift moves every bit in the stated direction, fills vacant positions with zeros, and keeps the stated width.", "tips": ["For a left shift, insert zeros on the right; bits shifted beyond the left edge are discarded.", "For a right shift, insert zeros on the left; bits shifted beyond the right edge are discarded.", "A one-place left shift doubles an unsigned value only when no significant bit is lost. A one-place right shift halves it, discarding any fractional part."]}, {"id": "W3-L2", "title": "Two's complement", "summary": "To represent a small negative number in eight-bit two's complement, write its positive magnitude, invert all eight bits, then add 1.", "tips": ["The most significant bit has weight -128 in eight-bit two's complement. The other weights are 64, 32, 16, 8, 4, 2 and 1.", "A most significant bit of 1 indicates a negative value; 0 indicates zero or a positive value.", "Keep all eight bits during the positive, inverted and final stages. Inversion alone does not complete the method."]}, {"id": "W4-L1", "title": "Integrated number-system practice", "summary": "Separate a contextual problem into reading the starting value, performing the required operation, and writing the requested representation.", "tips": ["Write down the base of each value before comparing or calculating.", "Use denary as a useful checking step when combining a count update with binary or hexadecimal.", "Treat independent parts as separate checks. Do not carry a result into a new part unless the question asks you to do so."]}, {"id": "W4-L2", "title": "ASCII and Unicode", "summary": "Character codes map numerical values to characters. Standard ASCII uses seven bits; Unicode covers many more writing systems.", "tips": ["Decode each binary code to denary, then use the supplied character table in the same order.", "For a multilingual requirement, connect Unicode’s wider character repertoire to the particular letters or script needed.", "Do not claim that every Unicode character always uses eight or sixteen bits. Different Unicode encodings represent characters differently."]}], "questions": [{"id": "g9-pf02b36bb", "number": 1, "label": "Practice 01", "title": "Read a new unsigned value", "marks": 1, "topics": ["W1-L1"], "context": [], "parts": [{"id": "a", "prompt": "What is the denary value of the unsigned 8-bit binary number 01010010?", "marks": 1, "blocks": [], "hint": "Label the binary places and include only the positions containing 1.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["74", "80", "82", "164"], "answer": 2, "marks": 1}], "steps": [{"title": "Locate the 1s", "text": "Using the unsigned weights 128, 64, 32, 16, 8, 4, 2, 1, the pattern selects 64, 16 and 2."}, {"title": "Add the selected weights", "text": "The zero positions make no contribution. Add the three selected weights to obtain denary.", "code": "64 + 16 + 2 = 82"}], "model": "C. 82. The 1s select 64, 16 and 2, which total 82.", "rubric": ["C. 82. The 1s select 64, 16 and 2, which total 82."]}], "kind": "mcq"}, {"id": "g9-p5cba1d7b", "number": 2, "label": "Practice 02", "title": "Read a two's-complement sign", "marks": 1, "topics": ["W3-L2"], "context": [], "parts": [{"id": "a", "prompt": "An 8-bit two's-complement number has 0 as its most significant bit. What can be concluded?", "marks": 1, "blocks": [], "hint": "Consider the weight of the most significant bit in this signed representation.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["It must represent zero.", "It represents zero or a positive value.", "It represents a negative value.", "It must represent an odd value."], "answer": 1, "marks": 1}], "steps": [{"title": "Identify the negative-weight place", "text": "In eight-bit two's complement, only the most significant position has negative weight: -128."}, {"title": "Apply the leading zero", "text": "When that bit is 0, the value comes only from the remaining non-negative place values. It may be zero or positive; it need not be odd."}], "model": "B. It represents zero or a positive value.\nA leading 0 indicates a non-negative two's-complement value.", "rubric": ["A leading 0 indicates a non-negative two's-complement value."]}], "kind": "mcq"}, {"id": "g9-p5fbc60cb", "number": 3, "label": "Practice 03", "title": "Match hexadecimal and bits", "marks": 1, "topics": ["W1-L2"], "context": [], "parts": [{"id": "a", "prompt": "How many binary bits correspond to one hexadecimal digit?", "marks": 1, "blocks": [], "hint": "Compare the number of possible values of a hexadecimal digit with the number of binary patterns.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["2", "3", "4", "8"], "answer": 2, "marks": 1}], "steps": [{"title": "Count hexadecimal values", "text": "A hexadecimal digit can take 16 values: 0 to 9, then A to F."}, {"title": "Find the matching binary width", "text": "Four binary places create 2 × 2 × 2 × 2 = 16 patterns. That is an exact match for one hexadecimal digit.", "code": "1 hexadecimal digit ↔ 4 bits"}], "model": "C. 4\nOne hexadecimal digit has 16 possible values, represented by four bits.", "rubric": ["One hexadecimal digit has 16 possible values, represented by four bits."]}], "kind": "mcq"}, {"id": "g9-pd6b70bf2", "number": 4, "label": "Practice 04", "title": "Checking counters and identification codes", "marks": 5, "topics": ["W4-L1"], "context": [{"type": "text", "text": "A club stores numerical identification codes and entry counts. All binary values in this question are unsigned. Treat each part as a separate check."}], "parts": [{"id": "a", "prompt": "A display shows denary 21 and hexadecimal 15 for the same identification code. State whether these values agree and justify your answer.", "marks": 1, "blocks": [], "hint": "Convert one representation into the other’s base, then make a comparison supported by working.", "widgets": [{"id": "agreement", "type": "choice", "label": "Choose a judgement with a valid justification", "options": ["They disagree because the written digits are different.", "They agree because hexadecimal 15 is 1 × 16 + 5 = 21 in denary.", "They agree because both numbers contain two digits.", "They disagree because hexadecimal 15 must mean denary 15."], "answer": 1, "marks": 1}], "steps": [{"title": "Interpret the hexadecimal display", "text": "The left digit 1 counts one group of 16. Add the right-hand digit 5.", "code": "Hexadecimal 15 = 1 × 16 + 5 = 21"}, {"title": "Compare equivalent values", "text": "The converted value is denary 21, matching the other display. Different written representations can express the same value."}], "model": "They agree because hexadecimal 15 is 1 × 16 + 5 = 21 in denary.", "rubric": ["States that the values agree and justifies this using 1 × 16 + 5 = 21 or an equivalent correct conversion."]}, {"id": "b", "prompt": "An 8-bit entry counter contains 00001100. Three more people enter. Calculate the new count and write it as an 8-bit binary value. Show your working.", "marks": 2, "blocks": [], "hint": "Read the initial count, apply the increase, and only then write the new count using eight bits.", "widgets": [{"id": "update", "type": "choice", "label": "Choose the correct count update", "options": ["12 + 3 = 14", "13 + 3 = 16", "12 + 3 = 15", "12 − 3 = 9"], "answer": 2, "marks": 1}, {"id": "counter", "type": "text", "label": "New 8-bit binary count", "answer": "00001111", "accept": ["00001111"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Read the starting count", "text": "The initial pattern has 1s in the 8 and 4 places, so it represents 12.", "code": "00001100 = 8 + 4 = 12"}, {"title": "Apply the change", "text": "Three more people means add 3 to the starting count. The updated value is 15.", "code": "12 + 3 = 15"}, {"title": "Return to an eight-bit representation", "text": "Fifteen is 8 + 4 + 2 + 1. Put 1s in those four low positions and keep leading zeros.", "code": "15 → 00001111"}], "model": "00001100 = 12. The updated count is 12 + 3 = 15, represented as 00001111.", "rubric": ["Correct working showing the starting count is 12 and the updated denary count is 15, or correct direct binary addition giving 15. An incorrect updated count does not earn this mark.", "Correct 8-bit representation 00001111. If the candidate obtains a different denary count in part (b), accept its correct 8-bit representation for this mark when that count lies within 0 to 255. The incorrect updated count loses the first mark, so the arithmetic error is penalised once."]}, {"id": "c", "prompt": "A separate counter shows hexadecimal 24. Write the count in denary.", "marks": 1, "blocks": [], "hint": "The left hexadecimal digit counts groups of 16.", "widgets": [{"id": "count", "type": "text", "label": "Counter value in denary", "answer": "36", "accept": ["36"], "normalize": "number", "marks": 1, "placeholder": "Type a denary number"}], "steps": [{"title": "Use the hexadecimal place values", "text": "The digits 2 and 4 represent two sixteens and four units."}, {"title": "Combine the contributions", "text": "Multiply before adding to obtain the count in denary.", "code": "2 × 16 + 4 = 36"}], "model": "2 × 16 + 4 = 36.", "rubric": ["Correct denary count 36."]}, {"id": "d", "prompt": "A new identification code has the denary value 64. Write this code in hexadecimal.", "marks": 1, "blocks": [], "hint": "Find how many complete groups of 16 fit into the denary value and what remains.", "widgets": [{"id": "code", "type": "text", "label": "Identification code in hexadecimal", "answer": "40", "accept": ["40", "0x40"], "normalize": "hex", "marks": 1, "placeholder": "Type a hexadecimal value"}], "steps": [{"title": "Divide into sixteens and units", "text": "The denary value 64 contains exactly four groups of 16, with no units remaining.", "code": "64 = 4 × 16 + 0"}, {"title": "Write the hexadecimal digits", "text": "Use 4 in the sixteens position and 0 in the units position.", "code": "64 in denary = 40 in hexadecimal"}], "model": "64 = 4 × 16 + 0, so the hexadecimal code is 40.", "rubric": ["Correct hexadecimal code 40. Accept 0x40."]}], "kind": "applied"}, {"id": "g9-pf42d7b9e", "number": 5, "label": "Practice 05", "title": "Check a device’s data representations", "marks": 5, "topics": ["W4-L1", "W1-L2", "W3-L1", "W2-L1"], "context": [{"type": "text", "text": "A club device stores numerical codes and counters. All binary values in this question are unsigned, with the widths stated. Complete each check independently."}], "parts": [{"id": "a", "prompt": "One identification value is shown as denary 58 and hexadecimal 3A. State whether the displays agree and justify your answer.", "marks": 1, "blocks": [], "hint": "Convert the hexadecimal value using its place values before judging the claim.", "widgets": [{"id": "agreement", "type": "choice", "label": "Choose a judgement supported by a correct conversion", "options": ["They disagree because A must have value 1.", "They agree because both displays use two digits.", "They agree because 3 × 16 + 10 = 58.", "They disagree because hexadecimal 3A is denary 310."], "answer": 2, "marks": 1}], "steps": [{"title": "Interpret the hexadecimal digits", "text": "Three is in the sixteens position, and A has denary value 10.", "code": "3A = 3 × 16 + 10"}, {"title": "Compare the two values", "text": "The calculation gives 58, matching the denary display. The identification values agree.", "code": "48 + 10 = 58"}], "model": "They agree because hexadecimal 3A is 3 × 16 + 10 = 58 in denary.", "rubric": ["Correct agreement judgement supported by 3 × 16 + 10 = 58 or an equivalent valid conversion. [1]"]}, {"id": "b", "prompt": "A separate identification code has denary value 90. Write it in hexadecimal.", "marks": 1, "blocks": [], "hint": "Find the quotient and remainder when the number is divided into groups of 16.", "widgets": [{"id": "code", "type": "text", "label": "Identification code in hexadecimal", "answer": "5A", "accept": ["5A", "5a", "0x5A", "0x5a"], "normalize": "hex", "marks": 1, "placeholder": "Type a hexadecimal value"}], "steps": [{"title": "Separate sixteens from units", "text": "Five groups of 16 contribute 80, leaving a remainder of 10.", "code": "90 = 5 × 16 + 10"}, {"title": "Write the hexadecimal digits", "text": "The left digit is 5. The remainder 10 is written A in hexadecimal.", "code": "90 in denary = 5A in hexadecimal"}], "model": "90 = 5 × 16 + 10, so the hexadecimal code is 5A.", "rubric": ["Correct hexadecimal value 5A. Accept lowercase a and an optional 0x prefix. [1]"]}, {"id": "c", "prompt": "The device logically shifts unsigned 8-bit 00100100 one place to the left. Write the 8-bit result.", "marks": 1, "blocks": [], "hint": "Move the complete pattern left and insert a zero at the right.", "widgets": [{"id": "shifted", "type": "text", "label": "8-bit result after the logical left shift", "answer": "01001000", "accept": ["01001000"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Move each position left", "text": "The 1s move to the next higher positions, and the empty rightmost position is filled with 0.", "code": "00100100 → 01001000"}, {"title": "Check that no significant bit was lost", "text": "The starting value is 36 and the result is 72. Both fit in eight unsigned bits, so this shift correctly doubles the value."}], "model": "01001000.", "rubric": ["Correct fixed-width logical left-shift result 01001000. [1]"]}, {"id": "d", "prompt": "A stored 8-bit value is displayed as hexadecimal 6D. A pupil says the two-digit display proves that only two bits are stored. Explain the mistake.", "marks": 1, "blocks": [], "hint": "Connect the number of bits represented by each hexadecimal digit to the two-digit display.", "widgets": [{"id": "explanation", "type": "choice", "label": "Choose the complete explanation", "options": ["Each hexadecimal digit represents four bits, so two digits still represent the stored eight-bit value.", "Every hexadecimal digit represents one bit, so the pupil is correct.", "Hexadecimal always changes the stored value into two bits.", "The display means the computer no longer stores a number."], "answer": 0, "marks": 1}], "steps": [{"title": "Expand each hexadecimal digit", "text": "Hexadecimal 6 corresponds to 0110, and D corresponds to 1101. Each digit therefore represents four binary bits.", "code": "6D → 0110 1101"}, {"title": "Distinguish representation from width", "text": "The two displayed digits represent 4 + 4 = 8 bits. The shorter notation does not reduce the stored width."}], "model": "Each hexadecimal digit corresponds to four bits, so the two digits 6D represent eight bits. The display does not reduce the stored width.", "rubric": ["Explains that two hexadecimal digits correspond to eight bits because each digit represents four bits; the display does not change the stored width. [1]"]}, {"id": "e", "prompt": "An unsigned 8-bit counter starts at 00010100. Two people enter. Write the updated count as an 8-bit binary value.", "marks": 1, "blocks": [], "hint": "Read the initial count, add the increase, then return to the required eight-bit representation.", "widgets": [{"id": "count", "type": "text", "label": "Updated 8-bit count", "answer": "00010110", "accept": ["00010110"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Read and update the count", "text": "The initial pattern represents 16 + 4 = 20. Two more people increase it to 22.", "code": "20 + 2 = 22"}, {"title": "Write the new binary pattern", "text": "Twenty-two is 16 + 4 + 2. Set those bits and keep all eight positions.", "code": "22 → 00010110"}], "model": "00010100 is denary 20. The updated count is 22, represented by 00010110.", "rubric": ["Correct updated 8-bit count 00010110. [1]"]}], "kind": "applied"}, {"id": "g9-p3727cac1", "number": 6, "label": "Practice 06", "title": "Independent number and character checks", "marks": 6, "topics": ["W1-L1", "W1-L2", "W3-L2", "W4-L1", "W4-L2"], "context": [{"type": "text", "text": "Treat every part as a separate check. Keep the bit widths stated, and use the supplied character table for the last part."}], "parts": [{"id": "a", "prompt": "Convert the unsigned 8-bit binary number 01000111 to denary. Show your working.", "marks": 2, "blocks": [], "hint": "Write the place values for all eight positions and add only the positions containing 1.", "widgets": [{"id": "working", "type": "choice", "label": "Place-value sum", "options": ["64 + 4 + 2 + 1", "64 + 8 + 2 + 1", "32 + 4 + 2 + 1", "64 + 4 + 2"], "answer": 0, "marks": 1}, {"id": "value", "type": "text", "label": "Denary value", "answer": "71", "accept": ["71"], "normalize": "number", "marks": 1, "placeholder": "Type a number"}], "steps": [{"title": "Select the active places", "text": "The eight place values are 128, 64, 32, 16, 8, 4, 2 and 1. The 1 bits select 64, 4, 2 and 1.", "code": "01000111 -> 64 + 4 + 2 + 1"}, {"title": "Add the selected values", "text": "Add those four contributions to obtain the denary value.", "code": "64 + 4 + 2 + 1 = 71"}], "model": "64 + 4 + 2 + 1 = 71.", "rubric": ["[1] Correct place-value working, selecting 64, 4, 2 and 1.", "[1] Denary result 71. Award independently of whether the guided working choice was correct."]}, {"id": "b", "prompt": "Write hexadecimal 6F as an unsigned 8-bit binary value.", "marks": 1, "blocks": [], "hint": "Translate each hexadecimal digit into four bits and preserve their order.", "widgets": [{"id": "binary", "type": "text", "label": "8-bit binary value", "answer": "01101111", "accept": ["01101111"], "normalize": "binary", "marks": 1, "placeholder": "Keep all eight bits"}], "steps": [{"title": "Convert each digit", "text": "Hexadecimal 6 is 0110 and hexadecimal F is 1111. Each digit needs its complete four-bit group."}, {"title": "Join the groups in order", "text": "Place the group for 6 first and the group for F second. Keep the leading zero.", "code": "0110 1111 -> 01101111"}], "model": "01101111.", "rubric": ["[1] 01101111, retaining all eight bits."]}, {"id": "c", "prompt": "The positive magnitude +14 is 00001110 in eight bits. As the inversion step of a two's-complement conversion, invert all eight bits. Write the resulting pattern.", "marks": 1, "blocks": [], "hint": "Change every 0 to 1 and every 1 to 0, including the leading positions.", "widgets": [{"id": "inverted", "type": "text", "label": "Pattern after inversion", "answer": "11110001", "accept": ["11110001"], "normalize": "binary", "marks": 1, "placeholder": "Keep all eight bits"}], "steps": [{"title": "Reverse each position", "text": "The leading four zeros become four ones. In the last four positions, 1110 becomes 0001."}, {"title": "Keep the full width", "text": "Join the inverted groups to give eight bits. This is the inversion step; adding one is a separate operation.", "code": "00001110 -> 11110001"}], "model": "11110001.", "rubric": ["[1] Inverted eight-bit pattern 11110001. Do not add one in this part."]}, {"id": "d", "prompt": "This is a separate conversion for -23. The positive magnitude has already been inverted to 11101000. Add 1 to obtain the final 8-bit two's-complement pattern.", "marks": 1, "blocks": [], "hint": "Use the supplied pattern for this part and begin the addition at the rightmost bit.", "widgets": [{"id": "signed", "type": "text", "label": "Final 8-bit pattern for -23", "answer": "11101001", "accept": ["11101001"], "normalize": "binary", "marks": 1, "placeholder": "Keep all eight bits"}], "steps": [{"title": "Start from the supplied inverted pattern", "text": "This part uses 11101000, independently of the preceding conversion. Add the eight-bit value 00000001."}, {"title": "Complete the addition", "text": "The final bit is 0, so adding 1 changes it to 1 without a carry into the next column. The other bits remain unchanged.", "code": "11101000 + 00000001 = 11101001"}], "model": "11101001, the 8-bit two's-complement representation of -23.", "rubric": ["[1] 11101001. Use the supplied starting pattern; this mark is independent of part (c)."]}, {"id": "e", "prompt": "Use the standard ASCII table to state the character represented by the 7-bit code 1010001.", "marks": 1, "blocks": [{"type": "table", "headers": ["Character", "P", "Q", "R"], "rows": [["Denary ASCII code", "80", "81", "82"]]}], "hint": "Convert the seven-bit pattern into its denary code, then use the exact character in the table.", "widgets": [{"id": "character", "type": "choice", "label": "Decoded character", "options": ["P", "Q", "R", "q"], "answer": 1, "marks": 1}], "steps": [{"title": "Read the code value", "text": "The 1 bits select 64, 16 and 1, giving the denary code 81.", "code": "1010001 -> 64 + 16 + 1 = 81"}, {"title": "Look up the character", "text": "The table maps 81 to uppercase Q. Character case matters; lowercase q is a different character."}], "model": "Q. The code is 64 + 16 + 1 = 81, which the table maps to uppercase Q.", "rubric": ["[1] Uppercase Q."]}], "kind": "structured"}, {"id": "g9-pd7b70d85", "number": 7, "label": "Practice 07", "title": "Reading hexadecimal displays", "marks": 5, "topics": ["W1-L2", "W2-L1"], "context": [{"type": "text", "text": "A technician reads numerical values from a device's diagnostic display. Answer each part independently."}], "parts": [{"id": "a", "prompt": "The display shows hexadecimal 2B. Calculate its denary value. Show your working.", "marks": 2, "blocks": [], "hint": "Give the left hexadecimal digit its base-16 place value, and translate the letter digit before adding.", "widgets": [{"id": "method", "type": "choice", "label": "Choose the correct place-value calculation", "options": ["2 × 10 + 11", "2 × 16 + 12", "2 × 16 + 11", "2 + 11"], "answer": 2, "marks": 1}, {"id": "denary", "type": "text", "label": "Denary value shown by the device", "answer": "43", "accept": ["43"], "normalize": "number", "marks": 1, "placeholder": "Type a denary number"}], "steps": [{"title": "Interpret each digit", "text": "The left digit 2 occupies the sixteens position. The right digit B represents denary 11."}, {"title": "Calculate the total", "text": "Use the positional weights to combine the two digits into one denary value.", "code": "2 × 16 + 11 = 32 + 11 = 43"}], "model": "B = 11, so 2 × 16 + 11 = 43.", "rubric": ["Correct substitution or method: 2 × 16 + 11.", "Correct denary value 43."]}, {"id": "b", "prompt": "Another location is displayed as hexadecimal 30. Write its unsigned 8-bit binary value.", "marks": 1, "blocks": [], "hint": "Convert each hexadecimal digit to a complete four-bit group and keep the original order.", "widgets": [{"id": "pattern", "type": "text", "label": "Unsigned 8-bit binary value", "answer": "00110000", "accept": ["00110000"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Make one group for each digit", "text": "Hexadecimal 3 becomes 0011, and hexadecimal 0 becomes 0000. Each group must have four bits."}, {"title": "Join the groups left to right", "text": "Put the group for 3 before the group for 0. Together they form the requested eight-bit value.", "code": "3  0 → 0011 0000 → 00110000"}], "model": "3 = 0011 and 0 = 0000, giving 00110000.", "rubric": ["Correct 8-bit result 00110000."]}, {"id": "c", "prompt": "A pupil says that hexadecimal 20 has the same value as denary 20. Explain why this statement is incorrect.", "marks": 1, "blocks": [], "hint": "Compare the place value of the left digit in base 16 with its place value in base 10.", "widgets": [{"id": "explanation", "type": "choice", "label": "Choose the correct explanation", "options": ["They are the same because the written digits look the same.", "Hexadecimal 20 equals 2 + 0, so it is denary 2.", "Hexadecimal 20 equals denary 200 because another zero is required.", "The left hexadecimal place has weight 16, so hexadecimal 20 is denary 32."], "answer": 3, "marks": 1}], "steps": [{"title": "Identify the base-dependent weight", "text": "A digit’s position matters. The second place from the right is worth 16 in hexadecimal, while it is worth 10 in denary."}, {"title": "Use the correct weight", "text": "The hexadecimal value contains two sixteens and no units. It therefore differs from denary 20.", "code": "Hexadecimal 20 = 2 × 16 + 0 = denary 32"}], "model": "Hexadecimal 20 is 2 × 16 + 0 = 32 in denary, so it is not denary 20.", "rubric": ["Explains that the left-hand place has weight 16, so hexadecimal 20 equals denary 32. Accept an equivalent correct explanation."]}, {"id": "d", "prompt": "When checking a hexadecimal code, the technician converts each hexadecimal digit into a four-bit binary group. Explain why this grouping works.", "marks": 1, "blocks": [], "hint": "Count the possibilities for one hexadecimal digit and for a group of four binary bits.", "widgets": [{"id": "grouping", "type": "choice", "label": "Choose why the four-bit grouping works", "options": ["One hexadecimal digit and four binary bits each have 16 possible values.", "Every hexadecimal digit has the denary value 4.", "Four binary bits can represent only four different patterns.", "Hexadecimal digits must always be written in groups of four."], "answer": 0, "marks": 1}], "steps": [{"title": "Count the hexadecimal choices", "text": "One hexadecimal digit can be 0 to 9 or A to F, making 16 choices."}, {"title": "Count four-bit patterns", "text": "Four bits have 2 × 2 × 2 × 2 = 16 combinations. Each combination matches exactly one hexadecimal digit, enabling direct conversion."}], "model": "A hexadecimal digit has 16 possible values, exactly matching the 16 patterns that four binary bits can represent.", "rubric": ["Explains that 16 possible hexadecimal digit values match the 16 possible four-bit binary patterns. Accept an equivalent statement linking one hexadecimal digit to exactly four bits."]}], "kind": "structured"}, {"id": "g9-p5abc58ec", "number": 8, "label": "Practice 08", "title": "Recall standard ASCII", "marks": 1, "topics": ["W4-L2"], "context": [], "parts": [{"id": "a", "prompt": "How many bits does standard ASCII use for one character code?", "marks": 1, "blocks": [], "hint": "The question specifies standard ASCII, so distinguish it from wider character encodings.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["4", "6", "7", "16"], "answer": 2, "marks": 1}], "steps": [{"title": "Identify the stated standard", "text": "Standard ASCII is a character coding system based on seven bits per code."}, {"title": "Check its capacity", "text": "Seven binary places provide 2 to the power of 7, or 128, different code values.", "code": "7 bits → 128 possible codes"}], "model": "C. 7\nStandard ASCII uses seven bits and provides 128 codes.", "rubric": ["Standard ASCII uses seven bits and provides 128 codes."]}], "kind": "mcq"}, {"id": "g9-pe72b2890", "number": 9, "label": "Practice 09", "title": "Look up a standard ASCII code", "marks": 1, "topics": ["W4-L2"], "context": [{"type": "text", "text": "Part of a standard ASCII character-code table is shown."}, {"type": "table", "headers": ["Character", "L", "M", "N"], "rows": [["Denary code", "76", "77", "78"]]}], "parts": [{"id": "a", "prompt": "Using the table, which 7-bit standard ASCII code represents the uppercase character M?", "marks": 1, "blocks": [], "hint": "Find the character’s denary code in the table, then express it using seven binary places.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["1001101", "1001100", "1001110", "1001111"], "answer": 0, "marks": 1}], "steps": [{"title": "Read the supplied character table", "text": "The table gives uppercase M the denary code 77. Do not use a neighbouring character’s code."}, {"title": "Convert the code using seven bits", "text": "Seventy-seven is 64 + 8 + 4 + 1. Use the seven positions from 64 down to 1.", "code": "77 → 1001101"}], "model": "A. 1001101. The table gives M as 77, and 77 = 64 + 8 + 4 + 1.", "rubric": ["A. 1001101. The table gives M as 77, and 77 = 64 + 8 + 4 + 1."]}], "kind": "mcq"}, {"id": "g9-p64bc68aa", "number": 10, "label": "Practice 10", "title": "Convert hexadecimal to denary", "marks": 1, "topics": ["W1-L2"], "context": [], "parts": [{"id": "a", "prompt": "What is the denary value of the hexadecimal number 2A?", "marks": 1, "blocks": [], "hint": "Identify the value of the letter digit and the weight of the left-hand position.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["42", "26", "210", "34"], "answer": 0, "marks": 1}], "steps": [{"title": "Interpret the digits", "text": "Hexadecimal uses A for denary 10. In a two-digit hexadecimal number, the left digit counts groups of 16."}, {"title": "Apply the place values", "text": "Two groups of 16 plus 10 give the same number in denary.", "code": "2A = 2 × 16 + 10 = 42"}], "model": "A. 42\nA is 10, so 2 × 16 + 10 = 42.", "rubric": ["A is 10, so 2 × 16 + 10 = 42."]}], "kind": "mcq"}, {"id": "g9-p3627c92e", "number": 11, "label": "Practice 11", "title": "Represent another writing system", "marks": 1, "topics": ["W4-L2"], "context": [], "parts": [{"id": "a", "prompt": "A text system must store both English and Hindi characters. Standard ASCII cannot represent all the required Hindi characters. Which change addresses this problem?", "marks": 1, "blocks": [], "hint": "A wider range of characters needs a character repertoire that includes those characters.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["Display the same ASCII codes in hexadecimal.", "Use Unicode to represent the characters.", "Add a leading zero to every standard ASCII code.", "Change every English letter to uppercase."], "answer": 1, "marks": 1}], "steps": [{"title": "Identify the limitation", "text": "Standard ASCII has a limited character repertoire. Changing the written form or padding of its codes does not add new characters."}, {"title": "Choose the representation with wider coverage", "text": "Unicode includes characters used by many writing systems, including the required Hindi characters. Its broader repertoire addresses the stated need."}], "model": "B. Use Unicode to represent the characters.", "rubric": ["[1] Select B: Use Unicode to represent the characters."]}], "kind": "mcq"}, {"id": "g9-p3827cc54", "number": 12, "label": "Practice 12", "title": "Check a result that fits", "marks": 1, "topics": ["W2-L2"], "context": [], "parts": [{"id": "a", "prompt": "An unsigned 8-bit register holds values from 0 to 255. A calculation adds denary 180 and 60. Which statement is correct?", "marks": 1, "blocks": [], "hint": "Compare the complete sum with the stated storage range, rather than treating every carry as overflow.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["No overflow occurs because the sum 240 is within 0 to 255.", "Overflow occurs whenever an addition has a carry in any column.", "Overflow occurs because 240 needs nine binary bits.", "No overflow occurs because an unsigned 8-bit register can hold 511."], "answer": 0, "marks": 1}], "steps": [{"title": "Calculate the complete result", "text": "Add the denary operands to obtain 240.", "code": "180 + 60 = 240"}, {"title": "Compare with the allowed range", "text": "240 is no greater than the maximum of 255, so it fits. It is 11110000 in eight-bit binary; an internal carry does not by itself mean overflow."}], "model": "A. No overflow occurs. The complete sum is 240, which fits in an unsigned 8-bit register.", "rubric": ["[1] Select A: No overflow occurs because the sum 240 is within 0 to 255."]}], "kind": "mcq"}, {"id": "g9-pe82b2a23", "number": 13, "label": "Practice 13", "title": "Convert, add and shift", "marks": 6, "topics": ["W1-L1", "W1-L2", "W2-L2", "W3-L1"], "context": [{"type": "text", "text": "Answer each part independently. All binary values in this question are unsigned."}], "parts": [{"id": "a", "prompt": "Convert the 8-bit binary number 01100110 to denary. Show your working.", "marks": 2, "blocks": [], "hint": "Use the place values under the 1s, then add them.", "widgets": [{"id": "method", "type": "choice", "label": "Choose the correct non-zero place values", "options": ["64 + 16 + 4 + 2", "64 + 32 + 4 + 2", "64 + 32 + 8 + 2", "128 + 32 + 4 + 2"], "answer": 1, "marks": 1}, {"id": "denary", "type": "text", "label": "Final denary value", "answer": "102", "accept": ["102"], "normalize": "number", "marks": 1, "placeholder": "Type a denary number"}], "steps": [{"title": "Locate the four 1s", "text": "The selected unsigned positions are 64, 32, 4 and 2. Each contributes its place value once."}, {"title": "Add the contributions", "text": "Adding these four values converts the pattern to denary.", "code": "64 + 32 + 4 + 2 = 102"}], "model": "01100110 = 64 + 32 + 4 + 2 = 102.", "rubric": ["Correct place-value working using 64, 32, 4 and 2, or another valid method. [1]", "Correct final denary value 102. [1]"]}, {"id": "b", "prompt": "Write hexadecimal 3C as an unsigned 8-bit binary value.", "marks": 1, "blocks": [], "hint": "Use one four-bit group for each hexadecimal digit and preserve the order.", "widgets": [{"id": "binary", "type": "text", "label": "Unsigned 8-bit binary value", "answer": "00111100", "accept": ["00111100"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Convert the digits separately", "text": "Hexadecimal 3 is 0011. Hexadecimal C is denary 12, represented by 1100."}, {"title": "Join two complete groups", "text": "Place the group for 3 first, then the group for C. The result contains eight bits.", "code": "3C → 0011 1100 → 00111100"}], "model": "3 = 0011 and C = 1100, so 3C = 00111100.", "rubric": ["Correct 8-bit result 00111100. [1]"]}, {"id": "c", "prompt": "Add the two unsigned 8-bit numbers below. Show your working and give an 8-bit result.", "marks": 2, "blocks": [{"type": "code", "text": "  00001101\n+ 00000110"}], "hint": "Add from the right, or first convert both operands to denary as a check.", "widgets": [{"id": "method", "type": "choice", "label": "Choose the equivalent denary addition", "options": ["12 + 6", "13 + 5", "13 + 6", "13 + 7"], "answer": 2, "marks": 1}, {"id": "sum", "type": "text", "label": "Unsigned 8-bit sum", "answer": "00010011", "accept": ["00010011"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Read the two operands", "text": "The first pattern is 8 + 4 + 1 = 13. The second is 4 + 2 = 6."}, {"title": "Add and check carries", "text": "Adding gives 19. In binary column addition, a carry travels from the fours column through the eights column.", "code": "  00001101\n+ 00000110\n= 00010011"}, {"title": "Check the final places", "text": "The result has 1s in the 16, 2 and 1 places, which total 19."}], "model": "00001101 + 00000110 = 00010011, equivalent to 13 + 6 = 19.", "rubric": ["Valid addition working with carries or an equivalent correct method. [1]", "Correct 8-bit sum 00010011. [1]"]}, {"id": "d", "prompt": "Perform a logical right shift of one place on unsigned 8-bit 00110000. Write the 8-bit result.", "marks": 1, "blocks": [], "hint": "Keep eight places and fill the vacant left-hand position with zero.", "widgets": [{"id": "shifted", "type": "text", "label": "8-bit result after shifting right", "answer": "00011000", "accept": ["00011000"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Move each bit once", "text": "Every bit moves one place right. The last 0 is discarded and the leftmost gap is filled with 0.", "code": "00110000 → 00011000"}, {"title": "Check the value", "text": "The starting value is 48. The resulting 16 and 8 positions total 24, consistent with halving this even unsigned value."}], "model": "00011000.", "rubric": ["Correct fixed-width logical right-shift result 00011000. [1]"]}], "kind": "structured"}, {"id": "g9-p3927cde7", "number": 14, "label": "Practice 14", "title": "Keep the width during a left shift", "marks": 1, "topics": ["W3-L1"], "context": [], "parts": [{"id": "a", "prompt": "The unsigned 8-bit pattern 10000001 is logically shifted one place to the left. Any bit that leaves the eight positions is discarded. What is the 8-bit result?", "marks": 1, "blocks": [], "hint": "Keep exactly eight positions: discard the bit that leaves on the left and insert a zero on the right.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["10000010", "01000000", "00000011", "00000010"], "answer": 3, "marks": 1}], "steps": [{"title": "Move the bits one position left", "text": "The leading 1 moves outside the available eight positions and is discarded. The other seven bits move left."}, {"title": "Fill the vacant position", "text": "A logical left shift inserts 0 on the right, producing 00000010. Because a significant bit was discarded, this stored result does not preserve the doubled value.", "code": "10000001 -> 00000010"}], "model": "D. 00000010. The leftmost 1 is discarded and a 0 enters on the right.", "rubric": ["[1] Select D: 00000010"]}], "kind": "mcq"}, {"id": "g9-p56ba1409", "number": 15, "label": "Practice 15", "title": "Character codes in a museum guide", "marks": 5, "topics": ["W4-L2"], "context": [{"type": "text", "text": "A museum guide stores English labels using standard ASCII. Part of its character-code table is shown."}, {"type": "table", "headers": ["Character", "A", "B", "C", "D"], "rows": [["Denary ASCII code", "65", "66", "67", "68"]]}], "parts": [{"id": "a", "prompt": "Decode the following three 7-bit ASCII codes. Show the denary code values and write the three-character label.", "marks": 2, "blocks": [{"type": "code", "text": "1000011   1000001   1000010"}], "hint": "Convert each seven-bit code separately, then look up its character in the supplied table without changing the order.", "widgets": [{"id": "codes", "type": "choice", "label": "Choose the denary code values in order", "options": ["65, 66, 67", "67, 65, 66", "67, 66, 65", "66, 65, 67"], "answer": 1, "marks": 1}, {"id": "label", "type": "choice", "label": "Choose the resulting three-character label", "options": ["ABC", "BAC", "CBA", "CAB"], "answer": 3, "marks": 1}], "steps": [{"title": "Decode each unsigned code", "text": "The leading 1 is in the 64 position. Add the selected low bits for each seven-bit pattern.", "code": "1000011 = 67\n1000001 = 65\n1000010 = 66"}, {"title": "Look up the codes in order", "text": "The table maps 67 to C, 65 to A and 66 to B. Keeping this order gives the label CAB.", "code": "67, 65, 66 → C, A, B → CAB"}], "model": "1000011 = 67, 1000001 = 65, and 1000010 = 66. The label is CAB.", "rubric": ["Correct denary code values 67, 65, 66 in order.", "Correct label CAB. Accept consistent correct table lookup from the candidate's own codes if those codes all appear in the supplied table."]}, {"id": "b", "prompt": "The museum now needs labels in English, Turkish and Arabic. Explain why Unicode is more suitable than standard ASCII for this requirement.", "marks": 2, "blocks": [], "hint": "First compare character coverage, then connect that difference to the languages required by the museum.", "widgets": [{"id": "coverage", "type": "choice", "label": "Choose the character-coverage explanation", "options": ["Unicode can represent fewer characters than standard ASCII.", "Unicode has a much wider character repertoire than standard ASCII.", "Standard ASCII includes every writing system.", "Unicode is limited to English letters."], "answer": 1, "marks": 1}, {"id": "requirement", "type": "choice", "label": "Choose the link to this museum’s requirement", "options": ["The labels no longer need any character codes.", "English digits can only be represented by Unicode.", "Unicode makes every language use the same alphabet.", "Unicode can represent the required Turkish-specific letters and Arabic characters."], "answer": 3, "marks": 1}], "steps": [{"title": "Compare the available characters", "text": "Standard ASCII provides a limited set of characters. Unicode includes a much larger repertoire across many writing systems."}, {"title": "Apply the difference to the requirement", "text": "The museum needs Turkish-specific letters and Arabic script, not just the characters available in standard ASCII. Unicode includes those characters, so it meets the multilingual need."}], "model": "Unicode has a much wider character repertoire, including Turkish-specific letters and Arabic characters that standard ASCII cannot represent.", "rubric": ["Unicode provides a larger or wider character repertoire than standard ASCII.", "Links that repertoire to the required Turkish-specific letters or Arabic script. Do not require a fixed number of bits for all Unicode characters."]}, {"id": "c", "prompt": "State what is meant by a character set.", "marks": 1, "blocks": [], "hint": "Think about the collection of symbols that a coding system is able to represent.", "widgets": [{"id": "definition", "type": "choice", "label": "Choose the definition of a character set", "options": ["A collection of characters that a system can represent, with codes assigned to them.", "A list of the memory addresses currently in use.", "A sequence of binary additions with carries.", "A method that shifts all character codes to the right."], "answer": 0, "marks": 1}], "steps": [{"title": "Identify what belongs in the set", "text": "A character set contains representable characters, such as letters, digits, punctuation and other symbols."}, {"title": "Connect characters to codes", "text": "A system uses codes to identify those characters. A character set describes the supported collection; it is not a list of memory locations."}], "model": "A collection of characters that a system can represent, with a code assigned to each character.", "rubric": ["A collection of characters that can be represented or recognised by a system. Accept a description that also mentions the code assigned to each character."]}], "kind": "structured"}, {"id": "g9-p5bba1be8", "number": 16, "label": "Practice 16", "title": "Fill a logical right shift", "marks": 1, "topics": ["W3-L1"], "context": [], "parts": [{"id": "a", "prompt": "During a logical right shift of an unsigned binary number, what enters the vacant position on the left?", "marks": 1, "blocks": [], "hint": "A logical shift preserves the width and uses a specified value in each newly vacant position.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["0", "1", "A copy of the rightmost bit", "Nothing, because the stored width always becomes shorter"], "answer": 0, "marks": 1}], "steps": [{"title": "Move the bits to the right", "text": "The leftmost position becomes empty as every bit moves one place right. The bit pushed beyond the right edge is discarded."}, {"title": "Use logical zero filling", "text": "A logical shift inserts 0 into the vacant left position. It does not rotate a bit around or copy a sign bit."}], "model": "A. 0\nA logical right shift fills the vacant leftmost position with zero.", "rubric": ["A logical right shift fills the vacant leftmost position with zero."]}], "kind": "mcq"}, {"id": "g9-pf52b3e9a", "number": 17, "label": "Practice 17", "title": "Decode a small negative value", "marks": 1, "topics": ["W3-L2"], "context": [], "parts": [{"id": "a", "prompt": "What is the denary value of the 8-bit two's-complement pattern 11111110?", "marks": 1, "blocks": [], "hint": "Use the signed weight of the most significant bit, or recover the positive magnitude by inversion and adding 1.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["-1", "-2", "2", "254"], "answer": 1, "marks": 1}], "steps": [{"title": "Recognise a negative pattern", "text": "The most significant bit is 1, so this is negative under the stated two's-complement interpretation."}, {"title": "Recover the magnitude", "text": "Invert all eight bits to obtain 00000001, then add 1 to obtain 00000010. The magnitude is 2, so the original value is -2.", "code": "11111110 → 00000001 → 00000010"}], "model": "B. -2. Inverting and adding 1 gives a magnitude of 2; the original two's-complement pattern is negative.", "rubric": ["B. -2. Inverting and adding 1 gives a magnitude of 2; the original two's-complement pattern is negative."]}], "kind": "mcq"}, {"id": "g9-p62bc6584", "number": 18, "label": "Practice 18", "title": "Read a binary value", "marks": 1, "topics": ["W1-L1"], "context": [], "parts": [{"id": "a", "prompt": "What is the denary value of the unsigned 8-bit binary number 00101101?", "marks": 1, "blocks": [], "hint": "Write the eight place values above the bits, then use only positions containing 1.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["43", "45", "53", "61"], "answer": 1, "marks": 1}], "steps": [{"title": "Set the place values", "text": "In unsigned eight-bit binary, the rightmost bit has value 1 and each position to its left doubles.", "code": "128  64  32  16  8  4  2  1"}, {"title": "Add the selected values", "text": "The 1s in 00101101 select 32, 8, 4 and 1. Their sum identifies the correct option.", "code": "32 + 8 + 4 + 1 = 45"}], "model": "B. 45\n32 + 8 + 4 + 1 = 45.", "rubric": ["32 + 8 + 4 + 1 = 45."]}], "kind": "mcq"}, {"id": "g9-p5bbc5a7f", "number": 19, "label": "Practice 19", "title": "Recognise minus one", "marks": 1, "topics": ["W3-L2"], "context": [], "parts": [{"id": "a", "prompt": "Which 8-bit two's-complement pattern represents -1?", "marks": 1, "blocks": [], "hint": "Use the positive magnitude, inversion and add-one method, keeping eight bits throughout.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["11111111", "10000001", "00000001", "11111110"], "answer": 0, "marks": 1}], "steps": [{"title": "Construct the negative pattern", "text": "Start with +1 as 00000001. Invert all eight bits to obtain 11111110, then add 1.", "code": "00000001 → 11111110 → 11111111"}, {"title": "Check the signed interpretation", "text": "The leading 1 has weight -128 in eight-bit two's complement. The remaining seven 1s total 127, giving -1.", "code": "-128 + 127 = -1"}], "model": "A. 11111111\nIn 8-bit two's complement, 11111111 represents -1.", "rubric": ["In 8-bit two's complement, 11111111 represents -1."]}], "kind": "mcq"}, {"id": "g9-pf32b3b74", "number": 20, "label": "Practice 20", "title": "Spot unsigned overflow", "marks": 1, "topics": ["W2-L2"], "context": [], "parts": [{"id": "a", "prompt": "An unsigned 8-bit register stores values from 0 to 255. A calculation adds denary 250 and 10. Which statement is correct?", "marks": 1, "blocks": [], "hint": "Judge the size of the complete sum, not just the sizes of its two inputs.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["There is no overflow because both input values fit in eight bits.", "The result is exactly 4, so no information is lost.", "The result must be negative because it is greater than 127.", "Unsigned overflow occurs because the complete result is 260, greater than 255."], "answer": 3, "marks": 1}], "steps": [{"title": "Find the complete result", "text": "Both operands fit individually, but their sum may not.", "code": "250 + 10 = 260"}, {"title": "Compare with the register range", "text": "The complete result 260 exceeds the maximum 255. Keeping only the low eight bits would lose part of the answer, so overflow occurs."}], "model": "D. The complete sum is 260, which is outside the unsigned eight-bit range 0 to 255.", "rubric": ["D. The complete sum is 260, which is outside the unsigned eight-bit range 0 to 255."]}], "kind": "mcq"}, {"id": "g9-pf62b402d", "number": 21, "label": "Practice 21", "title": "Compare two identification values", "marks": 1, "topics": ["W4-L1"], "context": [], "parts": [{"id": "a", "prompt": "Two displays show the same kind of unsigned identification value. Display A shows binary 00111000 and display B shows hexadecimal 38. Which statement is correct?", "marks": 1, "blocks": [], "hint": "Convert both displays to the same base, then compare the resulting values.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["They disagree because binary 00111000 is denary 38.", "They agree because both displays contain the digit 3.", "They disagree because hexadecimal digits cannot represent binary values.", "They agree because both represent denary 56."], "answer": 3, "marks": 1}], "steps": [{"title": "Read the binary display", "text": "The 1s select 32, 16 and 8, so the binary value is 56.", "code": "00111000 = 32 + 16 + 8 = 56"}, {"title": "Read the hexadecimal display", "text": "The left digit counts groups of 16. Its value is also 56, so the two displays agree.", "code": "38 in hexadecimal = 3 × 16 + 8 = 56"}], "model": "D. They agree: binary 00111000 is denary 56, and hexadecimal 38 is also denary 56.", "rubric": ["D. They agree: binary 00111000 is denary 56, and hexadecimal 38 is also denary 56."]}], "kind": "mcq"}, {"id": "g9-p60ba23c7", "number": 22, "label": "Practice 22", "title": "Binary addition and logical shifting", "marks": 5, "topics": ["W2-L2", "W3-L1"], "context": [], "parts": [{"id": "a", "prompt": "Add the two unsigned 8-bit numbers below. Show your working and give the 8-bit result.", "marks": 2, "blocks": [{"type": "code", "text": "  00010110\n+ 00000011"}], "hint": "Align the rightmost bits and work from right to left. You may also check by converting both operands to denary.", "widgets": [{"id": "method", "type": "choice", "label": "Choose the equivalent denary addition", "options": ["22 + 2", "20 + 3", "22 + 1", "22 + 3"], "answer": 3, "marks": 1}, {"id": "sum", "type": "text", "label": "Unsigned 8-bit sum", "answer": "00011001", "accept": ["00011001"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Identify the operands", "text": "The first number is 16 + 4 + 2 = 22; the second is 2 + 1 = 3. This gives an independent check on a binary column addition."}, {"title": "Include every carry", "text": "In the low columns, 1 + 1 produces a carried 1. Continue carrying to obtain the result below.", "code": "  00010110\n+ 00000011\n= 00011001"}, {"title": "Check the result and width", "text": "The sum is 25, which is 16 + 8 + 1. It fits within eight bits.", "code": "22 + 3 = 25"}], "model": "00010110 + 00000011 = 00011001 (22 + 3 = 25).", "rubric": ["Evidence of a valid addition method with carries, or an equivalent correct method.", "Correct 8-bit result 00011001."]}, {"id": "b", "prompt": "A different addition produces the denary result 257. State whether overflow occurs when this result must be stored as an unsigned 8-bit number. Give a reason.", "marks": 2, "blocks": [], "hint": "Use the range of an unsigned eight-bit value. A valid calculation may still exceed the storage capacity.", "widgets": [{"id": "occurs", "type": "choice", "label": "Does unsigned overflow occur?", "options": ["Yes", "No"], "answer": 0, "marks": 1}, {"id": "reason", "type": "choice", "label": "Choose the reason", "options": ["The leftmost bit of any binary number makes it negative.", "257 is greater than the maximum unsigned 8-bit value, 255.", "Every odd number needs nine bits.", "Only zero can be stored using eight bits."], "answer": 1, "marks": 1}], "steps": [{"title": "Find the largest allowed value", "text": "Eight unsigned bits can represent 0 to 255. The largest pattern, 11111111, equals 255."}, {"title": "Compare the complete result", "text": "The result is 257, which exceeds the allowed maximum. It therefore requires more than eight bits and causes unsigned overflow.", "code": "257 > 255"}], "model": "Yes. The maximum unsigned 8-bit value is 255, so 257 cannot fit.", "rubric": ["States that overflow occurs.", "Gives a correct reason: 257 is greater than 255 or requires more than eight bits."]}, {"id": "c", "prompt": "Perform a logical right shift of one place on the unsigned 8-bit value 00101000. Write the 8-bit result.", "marks": 1, "blocks": [], "hint": "Move each bit one place right, fill the left position with 0, and keep eight bits.", "widgets": [{"id": "shifted", "type": "text", "label": "8-bit result after the logical right shift", "answer": "00010100", "accept": ["00010100"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Move all positions once", "text": "The bits move right together. The rightmost 0 is discarded, and a new 0 enters at the left.", "code": "00101000 → 00010100"}, {"title": "Check using the value", "text": "The original unsigned value is 40. A one-place right shift gives 20 here, consistent with the resulting pattern.", "code": "00010100 = 16 + 4 = 20"}], "model": "00010100.", "rubric": ["Correct 8-bit result 00010100."]}], "kind": "structured"}, {"id": "g9-p5ebc5f38", "number": 23, "label": "Practice 23", "title": "Recognise a hexadecimal use", "marks": 1, "topics": ["W2-L1"], "context": [], "parts": [{"id": "a", "prompt": "Which item is commonly displayed using hexadecimal?", "marks": 1, "blocks": [], "hint": "Look for a numerical computer value that a technician may need to read.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["A user's full name", "An ordinary paragraph of text", "A written explanation of a calculation", "A computer memory address"], "answer": 3, "marks": 1}], "steps": [{"title": "Identify the kind of information", "text": "A memory address identifies a location in computer memory and can be written as a number."}, {"title": "Connect the display to its purpose", "text": "Hexadecimal makes long binary address values shorter to display and easier for people to inspect. Ordinary prose is not the numerical address being represented."}], "model": "D. A computer memory address\nMemory addresses are commonly displayed in hexadecimal.", "rubric": ["Memory addresses are commonly displayed in hexadecimal."]}], "kind": "mcq"}, {"id": "g9-p61ba255a", "number": 24, "label": "Practice 24", "title": "Preserve four-bit group order", "marks": 1, "topics": ["W4-L1"], "context": [], "parts": [{"id": "a", "prompt": "A pupil groups binary 00101111 as 0010 and 1111. These groups represent hexadecimal 2 and F. The pupil writes the final answer as F2. Which evaluation is correct?", "marks": 1, "blocks": [], "hint": "Work out which group is on the left and which is on the right before joining the digits.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["F2 is correct because hexadecimal digits must be written backwards.", "F2 is correct because binary groups may be placed in any order.", "The answer should be 2F because the groups must remain in their original order.", "Neither group can be represented by a hexadecimal digit."], "answer": 2, "marks": 1}], "steps": [{"title": "Keep each group in its position", "text": "The left four-bit group becomes the left hexadecimal digit, and the right group becomes the right digit."}, {"title": "Join without reversing", "text": "The supplied groups represent 2 followed by F. Reversing them changes the place values and therefore changes the number.", "code": "0010 1111 → 2F"}], "model": "C. The answer should be 2F because the groups must remain in their original order.\nThe order of the four-bit groups is preserved, giving 2F.", "rubric": ["The order of the four-bit groups is preserved, giving 2F."]}], "kind": "mcq"}, {"id": "g9-p55ba1276", "number": 25, "label": "Practice 25", "title": "Two's complement and hexadecimal", "marks": 5, "topics": ["W3-L2", "W2-L1"], "context": [], "parts": [{"id": "a", "prompt": "Represent -12 as an 8-bit two's-complement number. Show these three steps: write +12 in 8-bit binary, invert all eight bits, and add 1.", "marks": 3, "blocks": [], "hint": "Complete the three requested stages in order. Each stage must contain exactly eight bits.", "widgets": [{"id": "positive", "type": "text", "label": "Step 1: +12 in 8-bit binary", "answer": "00001100", "accept": ["00001100"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}, {"id": "inverted", "type": "text", "label": "Step 2: invert all eight bits", "answer": "11110011", "accept": ["11110011"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}, {"id": "negative", "type": "text", "label": "Step 3: add 1 to obtain -12", "answer": "11110100", "accept": ["11110100"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Write the positive magnitude", "text": "Twelve is 8 + 4. In an eight-bit pattern, set those two positions to 1.", "code": "+12 = 00001100"}, {"title": "Invert every bit", "text": "Replace each 0 with 1 and each 1 with 0. Include all leading positions.", "code": "00001100 → 11110011"}, {"title": "Add one", "text": "Add 00000001 to the inverted pattern. This completes the two's-complement method.", "code": "11110011 + 00000001 = 11110100"}, {"title": "Check the signed value", "text": "The leading 1 has weight -128. The other 1s contribute 64 + 32 + 16 + 4, so the total is -12.", "code": "-128 + 64 + 32 + 16 + 4 = -12"}], "model": "+12 = 00001100. Invert to obtain 11110011. Add 1 to obtain 11110100.", "rubric": ["Correct 8-bit representation of +12: 00001100.", "Correct inversion: 11110011. Accept the correct inversion of the candidate's own eight-bit positive pattern.", "Correct addition of 1 to obtain 11110100. Accept a correctly performed add-1 step on the candidate's own inverted eight-bit pattern; do not penalise the same earlier error again."]}, {"id": "b", "prompt": "The pattern 11111100 is an 8-bit two's-complement number. State whether it represents a positive or a negative value.", "marks": 1, "blocks": [], "hint": "Use the sign information carried by the most significant bit in two's complement.", "widgets": [{"id": "sign", "type": "choice", "label": "Sign of the represented value", "options": ["Positive", "Negative", "Zero"], "answer": 1, "marks": 1}], "steps": [{"title": "Identify the stated representation", "text": "The same pattern can be interpreted differently in unsigned binary and two's complement. This question explicitly uses two's complement."}, {"title": "Read the most significant bit", "text": "The leftmost bit is 1, which identifies a negative value in this representation. No full conversion is required."}], "model": "Negative.", "rubric": ["Negative."]}, {"id": "c", "prompt": "A technician must compare long computer memory addresses. Give one reason why displaying the addresses in hexadecimal can help the technician.", "marks": 1, "blocks": [], "hint": "Connect a property of hexadecimal to the technician’s task of reading and comparing long addresses.", "widgets": [{"id": "benefit", "type": "choice", "label": "Choose a reason linked to the task", "options": ["Hexadecimal automatically removes every error in an address.", "Hexadecimal changes addresses into smaller numerical values.", "Fewer displayed digits make long addresses easier to read and compare.", "Hexadecimal uses only two possible digits."], "answer": 2, "marks": 1}], "steps": [{"title": "Compare the length of the displays", "text": "Each hexadecimal digit replaces a group of four binary bits, so a long address needs fewer displayed digits."}, {"title": "Link the benefit to the technician", "text": "A shorter display can make the addresses easier to read, compare and copy accurately. Explain that practical benefit rather than claiming the stored value changes."}], "model": "Hexadecimal uses fewer digits than the equivalent binary representation, making long addresses easier to read, compare or copy accurately.", "rubric": ["Links a relevant benefit to the task, for example fewer displayed digits make addresses easier to read, compare or copy accurately. Accept fewer transcription errors as a linked benefit."]}], "kind": "structured"}, {"id": "g9-p65bc6a3d", "number": 26, "label": "Practice 26", "title": "Build an eight-bit pattern", "marks": 1, "topics": ["W1-L1"], "context": [], "parts": [{"id": "a", "prompt": "Which unsigned 8-bit binary number represents the denary value 26?", "marks": 1, "blocks": [], "hint": "Break the denary value into powers of two before placing the bits.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["00010110", "00011001", "00101010", "00011010"], "answer": 3, "marks": 1}], "steps": [{"title": "Decompose the denary value", "text": "Choose powers of two without exceeding 26. Using each binary place once gives 16, 8 and 2.", "code": "26 = 16 + 8 + 2"}, {"title": "Fill all eight places", "text": "Put 1s under 16, 8 and 2 and 0s elsewhere. Leading zeros retain the requested width.", "code": "00011010"}], "model": "D. 00011010\n26 = 16 + 8 + 2, giving 00011010.", "rubric": ["26 = 16 + 8 + 2, giving 00011010."]}], "kind": "mcq"}, {"id": "g9-p61bc63f1", "number": 27, "label": "Practice 27", "title": "Evaluate overflow", "marks": 1, "topics": ["W2-L2"], "context": [], "parts": [{"id": "a", "prompt": "An unsigned 8-bit location can store values from 0 to 255. An addition gives 256, written as 100000000 in binary. A pupil says that storing only the last eight bits preserves the answer exactly. Which evaluation is correct?", "marks": 1, "blocks": [], "hint": "Compare the full result with the stated storage range before considering which bits would remain.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["The pupil is correct because 00000000 is a valid 8-bit pattern.", "Overflow occurs because 256 is greater than 255.", "The result must be negative because its leftmost bit is 1.", "The addition is invalid because binary numbers cannot have nine bits."], "answer": 1, "marks": 1}], "steps": [{"title": "Check what eight bits can hold", "text": "Unsigned eight-bit storage can represent 0 to 255. A mathematically valid answer can still be too large for that location."}, {"title": "Check the discarded bit", "text": "The result 256 needs a ninth bit. Keeping only 00000000 would represent 0, so discarding the leading 1 loses the answer.", "code": "100000000 → only the last eight bits: 00000000"}], "model": "B. Overflow occurs because 256 is greater than 255.\nThe complete result is outside the stated range. Keeping only 00000000 loses the value 256.", "rubric": ["The complete result is outside the stated range. Keeping only 00000000 loses the value 256."]}], "kind": "mcq"}, {"id": "g9-p5dba1f0e", "number": 28, "label": "Practice 28", "title": "Understand Unicode coverage", "marks": 1, "topics": ["W4-L2"], "context": [], "parts": [{"id": "a", "prompt": "Which statement about Unicode is correct?", "marks": 1, "blocks": [], "hint": "Focus on which characters a coding system can represent, rather than assuming one storage width.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["It can represent only English letters and digits.", "It provides a much wider character set, including characters from many writing systems.", "Every Unicode character must be stored using exactly eight bits.", "Every Unicode character must be stored using exactly sixteen bits."], "answer": 1, "marks": 1}], "steps": [{"title": "Compare character repertoires", "text": "Unicode includes characters from many writing systems, so it can support far more characters than standard ASCII."}, {"title": "Separate repertoire from encoding", "text": "Unicode does not require every character in every encoding to use one universal eight-bit or sixteen-bit width. Its wider coverage is the correct statement."}], "model": "B. It provides a much wider character set, including characters from many writing systems.\nUnicode supports a large repertoire of characters. Its encodings do not all use one fixed number of bits per character.", "rubric": ["Unicode supports a large repertoire of characters. Its encodings do not all use one fixed number of bits per character."]}], "kind": "mcq"}, {"id": "g9-p3b27d10d", "number": 29, "label": "Practice 29", "title": "Read the width of a displayed address", "marks": 1, "topics": ["W2-L1"], "context": [], "parts": [{"id": "a", "prompt": "A memory address is displayed as hexadecimal 0A7C. How many binary bits do these four hexadecimal digits represent?", "marks": 1, "blocks": [], "hint": "Use the number of bits represented by one hexadecimal digit, then count all four digits.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["4", "8", "16", "32"], "answer": 2, "marks": 1}], "steps": [{"title": "Map one digit to a group", "text": "One hexadecimal digit represents a group of four binary bits."}, {"title": "Keep all four groups", "text": "The leading 0 still occupies a four-bit group in this display. Four groups contain 4 × 4 = 16 bits.", "code": "0 A 7 C\n0000 1010 0111 1100"}], "model": "C. 16 bits. Four hexadecimal digits represent four groups of four bits.", "rubric": ["[1] Select C: 16"]}], "kind": "mcq"}, {"id": "g9-p5eba20a1", "number": 30, "label": "Practice 30", "title": "Use the binary carry rule", "marks": 1, "topics": ["W2-L2"], "context": [], "parts": [{"id": "a", "prompt": "What is the binary result of adding 1 and 1?", "marks": 1, "blocks": [], "hint": "Binary has no single digit for denary two; consider the next place value.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["1", "11", "0", "10"], "answer": 3, "marks": 1}], "steps": [{"title": "Add the units column", "text": "Adding 1 and 1 gives denary 2. A binary units column can contain only 0 or 1."}, {"title": "Carry into the twos column", "text": "Write 0 in the units column and carry 1 to the twos column. The complete binary answer is 10.", "code": "1 + 1 = 10 in binary"}], "model": "D. 10\nBinary 1 + 1 gives 10: write 0 and carry 1 into the next column.", "rubric": ["Binary 1 + 1 gives 10: write 0 and carry 1 into the next column."]}], "kind": "mcq"}, {"id": "g9-pf12b384e", "number": 31, "label": "Practice 31", "title": "Interpret a hexadecimal letter", "marks": 1, "topics": ["W1-L2"], "context": [], "parts": [{"id": "a", "prompt": "What is the denary value of hexadecimal 4D?", "marks": 1, "blocks": [], "hint": "Use the sixteens position and translate the letter digit into denary.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["413", "77", "45", "93"], "answer": 1, "marks": 1}], "steps": [{"title": "Translate both positions", "text": "The left digit contributes four groups of 16. D is the hexadecimal digit for denary 13."}, {"title": "Calculate the total", "text": "Add the units contribution after multiplying by the positional weight.", "code": "4 × 16 + 13 = 64 + 13 = 77"}], "model": "B. 77. Hexadecimal D is denary 13, so 4D is 4 × 16 + 13 = 77.", "rubric": ["B. 77. Hexadecimal D is denary 13, so 4D is 4 × 16 + 13 = 77."]}], "kind": "mcq"}, {"id": "g9-pf52d7d31", "number": 32, "label": "Practice 32", "title": "Signed values, characters and readable codes", "marks": 6, "topics": ["W3-L2", "W4-L2", "W2-L1"], "context": [{"type": "text", "text": "The three parts are independent. For the character-code task, use the table supplied in part (b)."}], "parts": [{"id": "a", "prompt": "Represent -6 in 8-bit two's complement. Show +6 in eight-bit binary, invert all eight bits, then add 1.", "marks": 3, "blocks": [], "hint": "Write the positive magnitude first, and keep exactly eight bits at each stage.", "widgets": [{"id": "positive", "type": "text", "label": "Step 1: +6 in 8-bit binary", "answer": "00000110", "accept": ["00000110"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}, {"id": "inverted", "type": "text", "label": "Step 2: inverted 8-bit pattern", "answer": "11111001", "accept": ["11111001"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}, {"id": "negative", "type": "text", "label": "Step 3: 8-bit two's complement of -6", "answer": "11111010", "accept": ["11111010"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Write positive six", "text": "Six is 4 + 2, so the positive magnitude uses those two places.", "code": "+6 = 00000110"}, {"title": "Invert all eight positions", "text": "Change every 0 to 1 and every 1 to 0. The leading zeros must also be inverted.", "code": "00000110 → 11111001"}, {"title": "Add one to complete the method", "text": "Adding 1 produces the negative representation. A signed place-value check gives -128 + 64 + 32 + 16 + 8 + 2 = -6.", "code": "11111001 + 00000001 = 11111010"}], "model": "+6 = 00000110. Invert to obtain 11111001. Add 1 to obtain 11111010, which represents -6.", "rubric": ["Correct positive 8-bit pattern 00000110. [1]", "Correct inversion 11111001; on paper, accept a correct inversion of the candidate’s own eight-bit positive pattern. [1]", "Correct final pattern 11111010; on paper, accept a correctly performed add-one step on the candidate’s own inverted pattern without penalising the same earlier error again. [1]"]}, {"id": "b", "prompt": "Decode the two 7-bit standard ASCII codes below. Show their denary code values and write the two-character label.", "marks": 2, "blocks": [{"type": "table", "headers": ["Character", "H", "I", "J", "K"], "rows": [["Denary ASCII code", "72", "73", "74", "75"]]}, {"type": "code", "text": "1001000   1001001"}], "hint": "Convert each code separately, then use the supplied table in the same order.", "widgets": [{"id": "codes", "type": "choice", "label": "Denary codes in order", "options": ["73, 72", "72, 74", "74, 73", "72, 73"], "answer": 3, "marks": 1}, {"id": "label", "type": "choice", "label": "Two-character label", "options": ["HI", "IH", "HJ", "JK"], "answer": 0, "marks": 1}], "steps": [{"title": "Convert both codes", "text": "The first pattern uses 64 + 8; the second also includes the units bit.", "code": "1001000 = 72\n1001001 = 73"}, {"title": "Use the supplied mapping", "text": "The table maps 72 to H and 73 to I. Preserve the original code order to obtain HI."}], "model": "1001000 = 72 and 1001001 = 73. The two-character label is HI.", "rubric": ["Correct denary values 72 and 73 in order. [1]", "Correct label HI; on paper, accept consistent table lookup from the candidate’s own codes if both codes appear in the table. [1]"]}, {"id": "c", "prompt": "A technician compares two long diagnostic codes. Explain one benefit of displaying their numerical values in hexadecimal rather than binary.", "marks": 1, "blocks": [], "hint": "Explain how the number of displayed digits affects the technician’s comparison task.", "widgets": [{"id": "benefit", "type": "choice", "label": "Choose a benefit linked to the task", "options": ["Hexadecimal prevents all possible hardware faults.", "Fewer displayed digits make the long codes easier to read and compare.", "The hexadecimal display always needs only one bit.", "Changing the display changes each code to a smaller value."], "answer": 1, "marks": 1}], "steps": [{"title": "Relate hexadecimal digits to bits", "text": "One hexadecimal digit represents a group of four binary bits, reducing the number of displayed digits."}, {"title": "Connect that property to comparison", "text": "The shorter representation is easier for a person to scan and compare, which can also reduce copying mistakes."}], "model": "Hexadecimal uses fewer displayed digits for the same numerical values, making long diagnostic codes easier to read and compare.", "rubric": ["Links fewer displayed digits to easier reading, comparison or more accurate copying of the codes. Accept an equivalent relevant benefit. [1]"]}], "kind": "structured"}, {"id": "g9-pd5b70a5f", "number": 33, "label": "Practice 33", "title": "Updating values and checking a display", "marks": 5, "topics": ["W3-L1", "W2-L1"], "context": [{"type": "text", "text": "A device uses unsigned 8-bit values. Its display can show the same stored value in binary or hexadecimal. Answer the checks below independently."}], "parts": [{"id": "a", "prompt": "A count is 00000101 in binary. The device doubles it using a logical left shift of one place. Write the new 8-bit binary count.", "marks": 1, "blocks": [], "hint": "Move each bit left once, then insert 0 on the right while keeping eight positions.", "widgets": [{"id": "count", "type": "text", "label": "New 8-bit binary count", "answer": "00001010", "accept": ["00001010"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Perform the stated shift", "text": "The low 1s move one position left. A new 0 enters on the right and the eight-bit width stays fixed.", "code": "00000101 → 00001010"}, {"title": "Check the intended update", "text": "The original count is 5 and no significant bit is lost. The result is 10, which correctly doubles the count.", "code": "5 × 2 = 10"}], "model": "00001010.", "rubric": ["Correct 8-bit result 00001010."]}, {"id": "b", "prompt": "Another count is 00011000. The device performs a logical right shift of one place. Write both the new 8-bit binary value and its denary value.", "marks": 2, "blocks": [], "hint": "Complete the shift first, then use binary place values to interpret the shifted result.", "widgets": [{"id": "shifted", "type": "text", "label": "New 8-bit binary value", "answer": "00001100", "accept": ["00001100"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}, {"id": "denary", "type": "text", "label": "Denary value of the shifted result", "answer": "12", "accept": ["12"], "normalize": "number", "marks": 1, "placeholder": "Type a denary number"}], "steps": [{"title": "Shift within eight bits", "text": "Move 00011000 one place right, discard the last 0 and insert 0 at the left.", "code": "00011000 → 00001100"}, {"title": "Read the resulting places", "text": "The remaining 1s occupy the 8 and 4 places. Add them to obtain the new denary count.", "code": "8 + 4 = 12"}], "model": "The new binary value is 00001100, which is 12 in denary.", "rubric": ["Correct 8-bit shifted pattern 00001100.", "Correct denary value 12. Accept a consistent denary conversion of the candidate's own 8-bit shifted result."]}, {"id": "c", "prompt": "A stored byte is shown as binary 01010100 or hexadecimal 54. A pupil claims that the hexadecimal display means the byte now uses only two bits. Explain why the pupil is incorrect.", "marks": 2, "blocks": [], "hint": "Separate the number of displayed hexadecimal digits from the number of binary bits those digits represent.", "widgets": [{"id": "digit", "type": "choice", "label": "How many bits correspond to one hexadecimal digit?", "options": ["2 bits", "8 bits", "4 bits", "16 bits"], "answer": 2, "marks": 1}, {"id": "byte", "type": "choice", "label": "Choose the correct conclusion about the stored byte", "options": ["The byte shrinks to two bits because two digits are visible.", "The byte becomes sixteen bits because the base is sixteen.", "The stored byte no longer has a binary representation.", "The two hexadecimal digits still represent eight bits; the display does not change the stored width."], "answer": 3, "marks": 1}], "steps": [{"title": "Convert the individual digits", "text": "Hexadecimal 5 corresponds to 0101, and hexadecimal 4 corresponds to 0100. Each digit represents four bits.", "code": "54 → 0101 0100"}, {"title": "Count the represented bits", "text": "There are two groups of four bits, making eight bits. The shorter display changes notation, not the size of the stored byte.", "code": "2 × 4 = 8 bits"}], "model": "One hexadecimal digit represents four bits. Two hexadecimal digits therefore represent eight bits; changing the display does not change the stored byte's width.", "rubric": ["States that one hexadecimal digit corresponds to four bits.", "Explains that two hexadecimal digits represent eight bits, so the displayed byte still uses eight bits. Do not award the second mark for repeating only that there are two digits."]}], "kind": "applied"}, {"id": "g9-p62ba26ed", "number": 34, "label": "Practice 34", "title": "Interpret a diagnostic code", "marks": 1, "topics": ["W2-L1"], "context": [], "parts": [{"id": "a", "prompt": "A diagnostic report displays the hexadecimal error code A2. Which statement is correct?", "marks": 1, "blocks": [], "hint": "Separate a number’s displayed notation from its underlying numerical value.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["The code represents a value that can also be written in binary.", "The computer must store the code as the two ordinary text characters A and 2.", "Displaying the code in hexadecimal changes its numerical value.", "Hexadecimal can be used only for negative numbers."], "answer": 0, "marks": 1}], "steps": [{"title": "Recognise an alternative representation", "text": "A numerical error code can be displayed in hexadecimal for readability and can also be written as a binary value."}, {"title": "Avoid a storage assumption", "text": "The display A2 alone does not require the computer to store the two characters as text. As a numerical value, A2 can be represented by the eight bits below.", "code": "A2 in hexadecimal = 10100010 in binary"}], "model": "A. The code represents a value that can also be written in binary.\nHexadecimal provides a readable representation of a value that can also be expressed in binary.", "rubric": ["Hexadecimal provides a readable representation of a value that can also be expressed in binary."]}], "kind": "mcq"}, {"id": "g9-pf22b39e1", "number": 35, "label": "Practice 35", "title": "Read a diagnostic report", "marks": 1, "topics": ["W2-L1"], "context": [], "parts": [{"id": "a", "prompt": "A repair report displays the numerical diagnostic code 0F8C in hexadecimal. Why can this be useful to a technician?", "marks": 1, "blocks": [], "hint": "Relate the length of the displayed code to the person who must inspect it.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["It uses fewer displayed digits than the equivalent 16-bit binary code, making comparison easier.", "It means that the computer no longer represents numbers in binary.", "It turns every code into a negative number.", "It uses only the digits 0 to 9."], "answer": 0, "marks": 1}], "steps": [{"title": "Compare the representations", "text": "Four hexadecimal digits match four groups of four binary bits. A 16-bit pattern can therefore be displayed using four hexadecimal digits."}, {"title": "Explain the practical benefit", "text": "Fewer displayed digits make long codes easier for a technician to read and compare. The value remains the same."}], "model": "A. The shorter hexadecimal display makes the numerical code easier to read and compare with another code.", "rubric": ["A. The shorter hexadecimal display makes the numerical code easier to read and compare with another code."]}], "kind": "mcq"}, {"id": "g9-p5fba2234", "number": 36, "label": "Practice 36", "title": "Binary and denary conversions", "marks": 5, "topics": ["W1-L1", "W1-L2"], "context": [], "parts": [{"id": "a", "prompt": "Convert the unsigned 8-bit binary number 00110101 to denary. Show your working.", "marks": 2, "blocks": [], "hint": "Match the 1s to their binary place values, then add those values.", "widgets": [{"id": "method", "type": "choice", "label": "Choose the correct place-value working", "options": ["32 + 16 + 4 + 1", "32 + 8 + 4 + 1", "64 + 16 + 4 + 1", "32 + 16 + 2 + 1"], "answer": 0, "marks": 1}, {"id": "value", "type": "text", "label": "Final denary value", "answer": "53", "accept": ["53"], "normalize": "number", "marks": 1, "placeholder": "Type a denary number"}], "steps": [{"title": "Read the non-zero places", "text": "Write 128, 64, 32, 16, 8, 4, 2, 1 above the eight bits. The 1s select 32, 16, 4 and 1."}, {"title": "Add to obtain denary", "text": "The zero positions contribute nothing. Adding the selected places gives the final value.", "code": "32 + 16 + 4 + 1 = 53"}], "model": "32 + 16 + 4 + 1 = 53.", "rubric": ["Correct non-zero place values 32, 16, 4 and 1, or another valid conversion method.", "Correct final denary value 53."]}, {"id": "b", "prompt": "Convert the denary number 18 to an unsigned 8-bit binary number. Show your working.", "marks": 2, "blocks": [], "hint": "Find powers of two whose sum is the denary value, then use all eight bit positions.", "widgets": [{"id": "method", "type": "choice", "label": "Choose a correct powers-of-two decomposition", "options": ["16 + 1", "8 + 4 + 2", "16 + 2", "32 + 2"], "answer": 2, "marks": 1}, {"id": "pattern", "type": "text", "label": "Unsigned 8-bit result", "answer": "00010010", "accept": ["00010010"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Find the required place values", "text": "The largest usable power of two is 16. Subtracting it from 18 leaves 2.", "code": "18 = 16 + 2"}, {"title": "Place the 1s and retain the width", "text": "Use 1 in the 16 and 2 positions and 0 elsewhere. There are eight positions, including the leading zeros.", "code": "00010010"}], "model": "18 = 16 + 2, so the 8-bit pattern is 00010010.", "rubric": ["Correct method, such as 18 = 16 + 2 or valid repeated division by 2.", "Correct 8-bit result 00010010."]}, {"id": "c", "prompt": "Write the four-bit binary group for the hexadecimal digit A.", "marks": 1, "blocks": [], "hint": "Translate the letter digit to denary, then use the four place values 8, 4, 2 and 1.", "widgets": [{"id": "group", "type": "text", "label": "Four-bit binary group", "answer": "1010", "accept": ["1010"], "normalize": "binary", "marks": 1, "placeholder": "Keep every required bit"}], "steps": [{"title": "Interpret the hexadecimal digit", "text": "The hexadecimal digits continue after 9, so A represents denary 10."}, {"title": "Use four binary places", "text": "Ten is 8 + 2. Set those positions to 1 and retain a full four-bit group.", "code": "10 = 8 + 2 → 1010"}], "model": "A = 1010.", "rubric": ["Correct four-bit group 1010."]}], "kind": "structured"}, {"id": "g9-pf42b3d07", "number": 37, "label": "Practice 37", "title": "Shift a new pattern right", "marks": 1, "topics": ["W3-L1"], "context": [], "parts": [{"id": "a", "prompt": "The unsigned 8-bit pattern 00011110 undergoes a logical right shift of one place. What is the 8-bit result?", "marks": 1, "blocks": [], "hint": "Move the bits right together and use zero filling at the left.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["00111100", "00011100", "00001111", "10001111"], "answer": 2, "marks": 1}], "steps": [{"title": "Apply the logical shift", "text": "Move each bit one place right, discard the last 0 and insert 0 at the left.", "code": "00011110 → 00001111"}, {"title": "Check the change in value", "text": "The starting value is 30. The resulting low four 1s represent 15, consistent with a one-place unsigned right shift."}], "model": "C. 00001111. The leading position is filled with 0 and each original bit moves one place right.", "rubric": ["C. 00001111. The leading position is filled with 0 and each original bit moves one place right."]}], "kind": "mcq"}, {"id": "g9-p60bc625e", "number": 38, "label": "Practice 38", "title": "Shift left once", "marks": 1, "topics": ["W3-L1"], "context": [], "parts": [{"id": "a", "prompt": "The unsigned 8-bit value 00001001 is logically shifted one place to the left. What is the 8-bit result?", "marks": 1, "blocks": [], "hint": "Move each bit one position and decide what fills the newly empty position.", "widgets": [{"id": "answer", "type": "choice", "label": "Your answer", "options": ["00000100", "00001010", "00010010", "00010011"], "answer": 2, "marks": 1}], "steps": [{"title": "Move within a fixed width", "text": "In a logical left shift, every bit moves one place left. The result must still contain eight bits."}, {"title": "Fill the right edge with zero", "text": "Insert 0 at the right. No significant 1 is lost here, so the value changes from 9 to 18.", "code": "00001001 → 00010010"}], "model": "C. 00010010\nEach bit moves left and a zero enters on the right: 00010010.", "rubric": ["Each bit moves left and a zero enters on the right: 00010010."]}], "kind": "mcq"}], "animations": [{"id": "g9-binary-hex", "title": "One value, three number systems", "topic": "W1-L2", "caption": "Follow one unsigned eight-bit value through denary place values and four-bit hexadecimal groups.", "frames": [{"title": "Start with eight bits", "lines": ["Unsigned binary: 00110110"], "note": "Each binary position has its own power-of-two value."}, {"title": "Read the 1 positions", "lines": ["32 + 16 + 4 + 2 = 54", "Denary value: 54"], "note": "Add only the place values selected by 1s."}, {"title": "Make two four-bit groups", "lines": ["0011   0110"], "note": "Keep both groups in their original left-to-right order."}, {"title": "Replace each group", "lines": ["0011 = hexadecimal 3", "0110 = hexadecimal 6", "Hexadecimal value: 36"], "note": "One hexadecimal digit matches one complete four-bit group."}, {"title": "Check that the value is unchanged", "lines": ["Binary: 00110110", "Denary: 54", "Hexadecimal: 36"], "note": "These are three representations of the same numerical value."}]}, {"id": "g9-twos-complement", "title": "Build -12 in two's complement", "topic": "W3-L2", "caption": "Use eight bits throughout: write the positive magnitude, invert, add one, and check the signed result.", "frames": [{"title": "Write the positive magnitude", "lines": ["+12 = 8 + 4", "8-bit binary: 00001100"], "note": "Begin with the positive magnitude using all eight positions."}, {"title": "Invert all eight bits", "lines": ["Before: 00001100", "After:  11110011"], "note": "Change every 0 to 1 and every 1 to 0, including leading positions."}, {"title": "Add one", "lines": ["11110011 + 00000001", "Result: 11110100"], "note": "Adding one completes the two's-complement construction."}, {"title": "Interpret the leading bit", "lines": ["8-bit signed pattern: 11110100", "Most significant bit: weight -128"], "note": "The stated two's-complement interpretation makes the leading 1 negative."}, {"title": "Verify the represented value", "lines": ["-128 + 64 + 32 + 16 + 4", "Total: -12"], "note": "The signed place values confirm that the final pattern represents -12."}]}, {"id": "g9-add-shift", "title": "Carry, shift and check the width", "topic": "W2-L2", "caption": "See a binary carry, compare logical shifts, and recognise when an unsigned result exceeds eight bits.", "frames": [{"title": "Align an eight-bit addition", "lines": ["00000111", "+ 00000001"], "note": "Both operands are unsigned. Start adding in the rightmost column."}, {"title": "Carry from the right", "lines": ["Binary 1 + 1 = 10", "Write 0; carry 1"], "note": "The carried 1 continues through the next two columns containing 1s."}, {"title": "Read the complete sum", "lines": ["00000111 + 00000001", "Result: 00001000", "Denary check: 7 + 1 = 8"], "note": "The result fits in the available eight bits."}, {"title": "Shift the result left once", "lines": ["00001000 -> 00010000", "Denary: 8 -> 16"], "note": "A zero enters on the right. No significant bit is lost, so the value doubles."}, {"title": "Start again and shift right", "lines": ["Start again: 00001000", "Right shift: 00000100", "Denary: 8 -> 4"], "note": "This separate check starts from 8 again. A zero enters on the left."}, {"title": "Check an addition that is too large", "lines": ["11111111 + 00000001", "Full sum: 1 00000000", "256 > 255: unsigned overflow"], "note": "The complete result needs nine bits. Keeping only eight would lose its value."}]}], "bankVersion": 2, "challenge": {"minutes": 60, "marks": 50}};
